const BASE = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

export async function register(username, password){
  const res = await fetch(`${BASE}/register`, {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({username,password})});
  return res.json();
}

export async function login(username, password){
  const res = await fetch(`${BASE}/login`, {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({username,password})});
  return res.json();
}

export async function getSessions(userId){
  const res = await fetch(`${BASE}/sessions/${userId}`);
  return res.json();
}

export async function getUser(userId){
  const res = await fetch(`${BASE}/user/${userId}`);
  return res.json();
}

export async function updateUser(userId, data){
  const res = await fetch(`${BASE}/user/${userId}`, {method:'PUT', headers:{'Content-Type':'application/json'}, body: JSON.stringify(data)});
  return res.json();
}
